arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

:root{
  --black:#000000;
  --accent:#E6FF32;
  --burgundy:#7F2A23;
  --white:#FFFFFF;
  --gray-50:#F9FAFB;
  --gray-100:#F3F4F6;
  --gray-200:#E5E7EB;
  --gray-300:#D1D5DB;
  --gray-400:#9CA3AF;
  --gray-500:#6B7280;
  --gray-600:#4B5563;
  --gray-700:#374151;
  --gray-800:#1F2937;
  --gray-900:#111827;
  --indigo:#4F46E5;
  --indigo-light:#818CF8;
  --coral:#FF6B6B;
  --green:#10B981;
  --radius:12px;
  --radius-lg:16px;
  --radius-xl:24px;
  --shadow-sm:0 1px 2px rgba(0,0,0,.05);
  --shadow:0 4px 6px -1px rgba(0,0,0,.07),0 2px 4px -2px rgba(0,0,0,.05);
  --shadow-md:0 10px 15px -3px rgba(0,0,0,.08),0 4px 6px -4px rgba(0,0,0,.05);
  --shadow-lg:0 20px 25px -5px rgba(0,0,0,.1),0 8px 10px -6px rgba(0,0,0,.08);
  --transition:all .3s cubic-bezier(.4,0,.2,1);
}

html{scroll-behavior:smooth;-webkit-font-smoothing:antialiased}
body{font-family:'Plus Jakarta Sans',system-ui,-apple-system,sans-serif;color:var(--gray-800);line-height:1.6;background:var(--white);overflow-x:hidden}

a{color:inherit;text-decoration:none}
img{max-width:100%;display:block}
button{font-family:inherit;cursor:pointer;border:none;background:none}
ul{list-style:none}

.container{max-width:1200px;margin:0 auto;padding:0 24px}

/* ===== NAVBAR ===== */
.navbar{position:fixed;top:0;left:0;right:0;z-index:1000;background:rgba(255,255,255,.95);backdrop-filter:blur(12px);border-bottom:1px solid var(--gray-100);transition:var(--transition)}
.navbar .container{display:flex;align-items:center;justify-content:space-between;height:72px}
.nav-logo{font-size:1.5rem;font-weight:800;color:var(--black);display:flex;align-items:center;gap:8px}
.nav-logo span{color:var(--burgundy)}
.nav-links{display:flex;align-items:center;gap:32px}
.nav-links a{font-size:.9rem;font-weight:600;color:var(--gray-600);transition:var(--transition);position:relative}
.nav-links a:hover,.nav-links a.active{color:var(--black)}
.nav-links a::after{content:'';position:absolute;bottom:-4px;left:0;width:0;height:2px;background:var(--burgundy);transition:var(--transition)}
.nav-links a:hover::after,.nav-links a.active::after{width:100%}
.nav-cta{background:var(--black);color:var(--accent);padding:10px 24px;border-radius:50px;font-weight:700;font-size:.9rem;transition:var(--transition);white-space:nowrap}
.nav-cta:hover{background:var(--gray-800);transform:translateY(-1px);box-shadow:var(--shadow-md)}
.mobile-toggle{display:none;flex-direction:column;gap:5px;padding:8px}
.mobile-toggle span{width:24px;height:2px;background:var(--black);transition:var(--transition)}
.mobile-menu{display:none;position:fixed;top:72px;left:0;right:0;background:var(--white);border-bottom:1px solid var(--gray-200);padding:16px 24px;flex-direction:column;gap:16px;box-shadow:var(--shadow-md)}
.mobile-menu.active{display:flex}
.mobile-menu a{font-size:1rem;font-weight:600;color:var(--gray-700);padding:8px 0}

@media(max-width:900px){
  .nav-links{display:none}
  .mobile-toggle{display:flex}
}

/* ===== HERO ===== */
.hero{padding:140px 0 80px;background:linear-gradient(135deg,var(--black) 0%,#1a1a2e 50%,var(--burgundy) 100%);color:var(--white);position:relative;overflow:hidden}
.hero::before{content:'';position:absolute;top:-50%;right:-20%;width:600px;height:600px;background:radial-gradient(circle,rgba(230,255,50,.08) 0%,transparent 70%);border-radius:50%}
.hero::after{content:'';position:absolute;bottom:-30%;left:-10%;width:500px;height:500px;background:radial-gradient(circle,rgba(127,42,35,.15) 0%,transparent 70%);border-radius:50%}
.hero .container{position:relative;z-index:1}
.hero-content{max-width:720px;margin:0 auto;text-align:center}
.hero h1{font-size:clamp(2.2rem,5vw,3.5rem);font-weight:800;line-height:1.1;margin-bottom:20px;letter-spacing:-.02em}
.hero h1 .highlight{color:var(--accent)}
.hero p{font-size:clamp(1rem,2vw,1.2rem);color:rgba(255,255,255,.8);max-width:560px;margin:0 auto 32px;line-height:1.7}
.hero-btns{display:flex;gap:16px;justify-content:center;flex-wrap:wrap}
.btn-primary{background:var(--accent);color:var(--black);padding:14px 32px;border-radius:50px;font-weight:700;font-size:1rem;transition:var(--transition);display:inline-flex;align-items:center;gap:8px}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 8px 24px rgba(230,255,50,.3)}
.btn-secondary{background:rgba(255,255,255,.1);color:var(--white);padding:14px 32px;border-radius:50px;font-weight:700;font-size:1rem;border:1px solid rgba(255,255,255,.2);transition:var(--transition)}
.btn-secondary:hover{background:rgba(255,255,255,.2);transform:translateY(-2px)}

/* Hero tabs */
.hero-tabs{margin-top:48px}
.tab-toggle{display:flex;justify-content:center;gap:0;background:rgba(255,255,255,.1);border-radius:50px;padding:4px;max-width:380px;margin:0 auto 32px}
.tab-btn{flex:1;padding:10px 24px;border-radius:50px;font-weight:600;font-size:.9rem;color:rgba(255,255,255,.6);transition:var(--transition);text-align:center}
.tab-btn.active{background:var(--accent);color:var(--black)}
.tab-panel{display:none;animation:fadeUp .4s ease}
.tab-panel.active{display:block}
.tab-preview{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:var(--radius-lg);padding:32px;min-height:280px;display:flex;align-items:center;justify-content:center}
.preview-mockup{width:100%;max-width:700px;background:rgba(255,255,255,.08);border-radius:var(--radius);padding:24px;display:flex;flex-direction:column;gap:16px}
.mockup-topbar{display:flex;gap:8px;align-items:center;padding-bottom:12px;border-bottom:1px solid rgba(255,255,255,.1)}
.mockup-dot{width:10px;height:10px;border-radius:50%}
.mockup-dot:nth-child(1){background:#FF5F57}
.mockup-dot:nth-child(2){background:#FFBD2E}
.mockup-dot:nth-child(3){background:#28C840}
.mockup-sidebar{display:flex;gap:16px}
.mockup-nav{width:180px;display:flex;flex-direction:column;gap:8px}
.mockup-nav-item{padding:8px 12px;border-radius:6px;font-size:.75rem;color:rgba(255,255,255,.5)}
.mockup-nav-item.active{background:var(--accent);color:var(--black);font-weight:600}
.mockup-main{flex:1;display:flex;flex-direction:column;gap:12px}
.mockup-card{background:rgba(255,255,255,.06);border-radius:8px;padding:16px}
.mockup-card h4{font-size:.8rem;color:var(--accent);margin-bottom:4px}
.mockup-card p{font-size:.7rem;color:rgba(255,255,255,.4)}
.mockup-row{display:flex;gap:12px}
.mockup-row .mockup-card{flex:1}
.student-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.student-course-card{background:rgba(255,255,255,.06);border-radius:8px;overflow:hidden}
.scc-img{height:80px;background:linear-gradient(135deg,rgba(127,42,35,.3),rgba(79,70,229,.3))}
.scc-body{padding:10px}
.scc-body h4{font-size:.75rem;color:var(--white);margin-bottom:4px}
.scc-body p{font-size:.65rem;color:rgba(255,255,255,.4)}
.scc-progress{height:4px;background:rgba(255,255,255,.1);border-radius:2px;margin-top:6px}
.scc-progress span{display:block;height:100%;background:var(--accent);border-radius:2px}

@media(max-width:640px){
  .mockup-sidebar{flex-direction:column}
  .mockup-nav{width:100%;flex-direction:row;overflow-x:auto}
  .student-grid{grid-template-columns:1fr}
  .mockup-row{flex-direction:column}
}

/* ===== STATS BAR ===== */
.stats-bar{background:var(--black);padding:32px 0}
.stats-bar .container{display:flex;justify-content:center;gap:64px;flex-wrap:wrap}
.stat-item{text-align:center}
.stat-value{font-size:clamp(1.8rem,4vw,2.5rem);font-weight:800;color:var(--accent);letter-spacing:-.02em}
.stat-label{font-size:.9rem;color:rgba(255,255,255,.6);margin-top:4px}

@media(max-width:640px){.stats-bar .container{gap:32px}}

/* ===== SECTION BASE ===== */
.section{padding:96px 0}
.section-alt{background:var(--gray-50)}
.section-dark{background:var(--black);color:var(--white)}
.section-header{text-align:center;max-width:680px;margin:0 auto 56px}
.section-header .label{font-size:.85rem;font-weight:700;color:var(--burgundy);text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px}
.section-header h2{font-size:clamp(1.8rem,4vw,2.8rem);font-weight:800;color:var(--black);line-height:1.15;letter-spacing:-.02em}
.section-dark .section-header h2{color:var(--white)}
.section-header p{font-size:1.05rem;color:var(--gray-500);margin-top:16px;line-height:1.7}
.section-dark .section-header p{color:rgba(255,255,255,.6)}

/* ===== PRODUCT CARDS ===== */
.product-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:24px}
.product-card{background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius-lg);padding:32px;transition:var(--transition);position:relative;overflow:hidden}
.product-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg);border-color:var(--accent)}
.product-card .icon{width:56px;height:56px;border-radius:var(--radius);display:flex;align-items:center;justify-content:center;font-size:1.6rem;margin-bottom:16px}
.product-card h3{font-size:1.2rem;font-weight:700;margin-bottom:8px}
.product-card p{font-size:.95rem;color:var(--gray-500);line-height:1.6}
.icon-courses{background:linear-gradient(135deg,#EEF2FF,#C7D2FE);color:#4F46E5}
.icon-coaching{background:linear-gradient(135deg,#FEF2F2,#FECACA);color:#DC2626}
.icon-downloads{background:linear-gradient(135deg,#ECFDF5,#A7F3D0);color:#059669}
.icon-memberships{background:linear-gradient(135deg,#FFFBEB,#FDE68A);color:#D97706}

/* ===== WHY CHOOSE US TABS ===== */
.why-tabs{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-bottom:40px}
.why-tab{padding:12px 24px;border-radius:50px;font-weight:600;font-size:.9rem;color:var(--gray-500);background:var(--gray-100);transition:var(--transition);border:2px solid transparent}
.why-tab:hover{color:var(--black);background:var(--gray-200)}
.why-tab.active{background:var(--black);color:var(--accent);border-color:var(--black)}
.why-panel{display:none;animation:fadeUp .4s ease}
.why-panel.active{display:block}
.why-features{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px}
.why-feature{display:flex;align-items:flex-start;gap:12px;padding:20px;background:var(--white);border-radius:var(--radius);border:1px solid var(--gray-200);transition:var(--transition)}
.why-feature:hover{border-color:var(--accent);box-shadow:var(--shadow)}
.why-feature .check{flex-shrink:0;width:24px;height:24px;border-radius:50%;background:var(--accent);color:var(--black);display:flex;align-items:center;justify-content:center;font-size:.75rem;font-weight:700}
.why-feature span{font-size:.95rem;font-weight:500;color:var(--gray-700)}

/* ===== FEATURE CARDS ===== */
.feature-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:24px}
.feature-card{background:var(--white);border-radius:var(--radius-lg);padding:36px;border:1px solid var(--gray-200);transition:var(--transition)}
.feature-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg)}
.feature-card .f-icon{width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#d4e82c);display:flex;align-items:center;justify-content:center;font-size:1.3rem;margin-bottom:16px}
.feature-card h3{font-size:1.15rem;font-weight:700;margin-bottom:8px}
.feature-card p{font-size:.95rem;color:var(--gray-500);line-height:1.6}

/* ===== TESTIMONIALS ===== */
.testimonials-section{overflow:hidden}
.testimonial-carousel{display:flex;gap:24px;overflow-x:auto;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;padding:8px 4px;scrollbar-width:none}
.testimonial-carousel::-webkit-scrollbar{display:none}
.testimonial-card{flex:0 0 360px;scroll-snap-align:start;background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius-lg);padding:32px;transition:var(--transition)}
.testimonial-card:hover{box-shadow:var(--shadow-md)}
.testimonial-tag{display:inline-block;background:var(--accent);color:var(--black);padding:4px 12px;border-radius:50px;font-size:.75rem;font-weight:700;margin-bottom:16px}
.testimonial-card blockquote{font-size:1rem;color:var(--gray-600);line-height:1.7;margin-bottom:20px;font-style:italic}
.testimonial-author{display:flex;align-items:center;gap:12px}
.testimonial-avatar{width:44px;height:44px;border-radius:50%;background:linear-gradient(135deg,var(--burgundy),var(--indigo));display:flex;align-items:center;justify-content:center;color:var(--white);font-weight:700;font-size:.9rem}
.testimonial-info h4{font-size:.9rem;font-weight:700;color:var(--gray-800)}
.testimonial-info p{font-size:.8rem;color:var(--gray-400)}
.carousel-controls{display:flex;justify-content:center;gap:12px;margin-top:32px}
.carousel-btn{width:44px;height:44px;border-radius:50%;border:2px solid var(--gray-300);display:flex;align-items:center;justify-content:center;font-size:1.1rem;color:var(--gray-500);transition:var(--transition)}
.carousel-btn:hover{border-color:var(--black);color:var(--black);background:var(--gray-50)}

/* ===== PRICING ===== */
.pricing-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:24px;max-width:900px;margin:0 auto}
.pricing-card{background:var(--white);border:2px solid var(--gray-200);border-radius:var(--radius-xl);padding:36px;text-align:center;transition:var(--transition);position:relative}
.pricing-card.featured{border-color:var(--accent);background:var(--black);color:var(--white)}
.pricing-card.featured .pricing-badge{position:absolute;top:-14px;left:50%;transform:translateX(-50%);background:var(--accent);color:var(--black);padding:4px 20px;border-radius:50px;font-size:.8rem;font-weight:700}
.pricing-card h3{font-size:1.2rem;font-weight:700;margin-bottom:8px}
.pricing-card .price{font-size:2.5rem;font-weight:800;margin-bottom:4px}
.pricing-card .period{font-size:.9rem;color:var(--gray-400);margin-bottom:24px}
.pricing-features{text-align:left;margin-bottom:28px}
.pricing-features li{padding:8px 0;font-size:.9rem;color:var(--gray-600);display:flex;align-items:center;gap:8px}
.pricing-card.featured .pricing-features li{color:rgba(255,255,255,.7)}
.pricing-features li::before{content:'✓';color:var(--green);font-weight:700}
.pricing-card .btn-pricing{display:block;width:100%;padding:14px;border-radius:50px;font-weight:700;font-size:1rem;transition:var(--transition)}
.btn-pricing-primary{background:var(--accent);color:var(--black)}
.btn-pricing-primary:hover{box-shadow:0 8px 24px rgba(230,255,50,.3);transform:translateY(-2px)}
.btn-pricing-outline{border:2px solid var(--gray-300);color:var(--gray-700)}
.btn-pricing-outline:hover{border-color:var(--black);color:var(--black);transform:translateY(-2px)}

/* ===== INTEGRATIONS ===== */
.integrations-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:16px}
.integration-item{display:flex;flex-direction:column;align-items:center;gap:8px;padding:24px 16px;background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius);transition:var(--transition)}
.integration-item:hover{border-color:var(--accent);box-shadow:var(--shadow);transform:translateY(-2px)}
.integration-icon{width:48px;height:48px;border-radius:10px;background:var(--gray-100);display:flex;align-items:center;justify-content:center;font-size:.9rem;font-weight:700;color:var(--gray-600)}
.integration-item span{font-size:.85rem;font-weight:600;color:var(--gray-700);text-align:center}

/* ===== FAQ ===== */
.faq-list{max-width:768px;margin:0 auto;display:flex;flex-direction:column;gap:12px}
.faq-item{border:1px solid var(--gray-200);border-radius:var(--radius);overflow:hidden;transition:var(--transition)}
.faq-item:hover{border-color:var(--gray-300)}
.faq-item.active{border-color:var(--accent)}
.faq-question{width:100%;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;font-size:1rem;font-weight:600;color:var(--gray-800);text-align:left;background:transparent;transition:var(--transition)}
.faq-question:hover{color:var(--black)}
.faq-icon{width:28px;height:28px;border-radius:50%;background:var(--gray-100);display:flex;align-items:center;justify-content:center;font-size:.8rem;transition:var(--transition);flex-shrink:0}
.faq-item.active .faq-icon{background:var(--accent);transform:rotate(180deg)}
.faq-answer{max-height:0;overflow:hidden;transition:max-height .3s ease}
.faq-answer-inner{padding:0 24px 20px;font-size:.95rem;color:var(--gray-500);line-height:1.7}

/* ===== FOOTER ===== */
.footer{background:var(--black);color:var(--white);padding:80px 0 32px}
.footer-grid{display:grid;grid-template-columns:2fr repeat(4,1fr);gap:40px;margin-bottom:48px}
.footer-brand h3{font-size:1.5rem;font-weight:800;margin-bottom:12px}
.footer-brand h3 span{color:var(--accent)}
.footer-brand p{font-size:.9rem;color:rgba(255,255,255,.5);line-height:1.7;max-width:280px}
.footer-col h4{font-size:.85rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--accent);margin-bottom:16px}
.footer-col a{display:block;font-size:.9rem;color:rgba(255,255,255,.6);padding:4px 0;transition:var(--transition)}
.footer-col a:hover{color:var(--white);padding-left:4px}
.footer-bottom{border-top:1px solid rgba(255,255,255,.1);padding-top:24px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:16px}
.footer-bottom p{font-size:.85rem;color:rgba(255,255,255,.4)}

@media(max-width:900px){
  .footer-grid{grid-template-columns:repeat(2,1fr)}
}
@media(max-width:640px){
  .footer-grid{grid-template-columns:1fr}
}

/* ===== CTA BANNER ===== */
.cta-banner{background:linear-gradient(135deg,var(--black),#1a1a2e,var(--burgundy));padding:80px 0;text-align:center;position:relative;overflow:hidden}
.cta-banner::before{content:'';position:absolute;top:-40%;right:-10%;width:400px;height:400px;background:radial-gradient(circle,rgba(230,255,50,.1),transparent 70%);border-radius:50%}
.cta-banner h2{font-size:clamp(1.8rem,4vw,2.8rem);font-weight:800;color:var(--white);margin-bottom:16px}
.cta-banner p{color:rgba(255,255,255,.7);font-size:1.1rem;margin-bottom:32px;max-width:500px;margin-left:auto;margin-right:auto}
.cta-banner .btn-primary{font-size:1.1rem;padding:16px 40px}

/* ===== TOOLS GRID ===== */
.tools-container{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px}
.tool-category{background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius);padding:24px}
.tool-category h3{font-size:1rem;font-weight:700;color:var(--burgundy);margin-bottom:12px;display:flex;align-items:center;gap:8px}
.tool-tag{display:inline-block;padding:4px 10px;background:var(--gray-100);border-radius:6px;font-size:.8rem;font-weight:500;color:var(--gray-600);margin:3px}

/* ===== STEPS ===== */
.steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:32px;counter-reset:step}
.step{position:relative;padding:32px;background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius-lg);transition:var(--transition);counter-increment:step}
.step:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg)}
.step::before{content:counter(step);position:absolute;top:-16px;left:24px;width:40px;height:40px;border-radius:50%;background:var(--black);color:var(--accent);font-weight:800;font-size:1.1rem;display:flex;align-items:center;justify-content:center}
.step h3{font-size:1.15rem;font-weight:700;margin:8px 0}
.step p{font-size:.95rem;color:var(--gray-500);line-height:1.6}

/* ===== SPOTLIGHT ===== */
.spotlight-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:24px}
.spotlight-card{background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius-lg);overflow:hidden;transition:var(--transition)}
.spotlight-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg)}
.spotlight-img{height:180px;background:linear-gradient(135deg,var(--black),var(--burgundy));display:flex;align-items:center;justify-content:center;font-size:2rem;color:var(--accent)}
.spotlight-body{padding:24px}
.spotlight-body h3{font-size:1.1rem;font-weight:700;margin-bottom:8px}
.spotlight-body p{font-size:.9rem;color:var(--gray-500);line-height:1.6}

/* ===== RESOURCES ===== */
.resource-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:24px}
.resource-card{background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius-lg);padding:28px;transition:var(--transition)}
.resource-card:hover{border-color:var(--accent);box-shadow:var(--shadow);transform:translateY(-2px)}
.resource-card .r-tag{display:inline-block;font-size:.75rem;font-weight:700;color:var(--burgundy);text-transform:uppercase;letter-spacing:.05em;margin-bottom:12px}
.resource-card h3{font-size:1.1rem;font-weight:700;margin-bottom:8px}
.resource-card p{font-size:.9rem;color:var(--gray-500);line-height:1.6}

/* ===== FILE TYPES ===== */
.file-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:16px}
.file-card{text-align:center;padding:28px 16px;background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius);transition:var(--transition)}
.file-card:hover{border-color:var(--accent);transform:translateY(-4px);box-shadow:var(--shadow)}
.file-card .file-icon{font-size:2rem;margin-bottom:8px}
.file-card h4{font-size:.95rem;font-weight:600;color:var(--gray-700)}

/* ===== MEMBERSHIP FEATURES ===== */
.membership-features{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:24px}
.membership-card{padding:32px;border-radius:var(--radius-lg);text-align:center;transition:var(--transition)}
.membership-card.highlight{background:var(--black);color:var(--white);border-radius:var(--radius-xl)}
.membership-card .m-value{font-size:2.5rem;font-weight:800;color:var(--accent);margin-bottom:8px}
.membership-card h3{font-size:1.2rem;font-weight:700;margin-bottom:8px}
.membership-card p{font-size:.95rem;color:var(--gray-500);line-height:1.6}
.membership-card.highlight p{color:rgba(255,255,255,.6)}

/* ===== SOCIAL PROOF BAR ===== */
.social-proof{background:var(--gray-50);padding:40px 0}
.social-proof .container{text-align:center}
.social-proof p{font-size:1rem;color:var(--gray-500);font-weight:500}
.social-proof strong{color:var(--black)}

/* ===== GLOBAL SCALE SECTION ===== */
.global-content{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:center}
.global-map{position:relative;height:320px;background:var(--gray-100);border-radius:var(--radius-lg);overflow:hidden;display:flex;align-items:center;justify-content:center}
.global-map-pattern{font-size:5rem;opacity:.3}
.global-text h3{font-size:1.5rem;font-weight:700;margin-bottom:12px}
.global-text p{font-size:1rem;color:var(--gray-500);line-height:1.7;margin-bottom:20px}
.global-stats{display:flex;gap:32px}
.global-stat .gs-val{font-size:1.5rem;font-weight:800;color:var(--burgundy)}
.global-stat .gs-label{font-size:.85rem;color:var(--gray-400)}

@media(max-width:768px){
  .global-content{grid-template-columns:1fr}
}

/* ===== AI SECTION ===== */
.ai-features{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px}
.ai-chip{display:flex;align-items:center;gap:10px;padding:16px 20px;background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius);transition:var(--transition);font-size:.9rem;font-weight:600;color:var(--gray-700)}
.ai-chip:hover{border-color:var(--accent);box-shadow:var(--shadow);transform:translateY(-2px)}
.ai-chip .ai-dot{width:8px;height:8px;border-radius:50%;background:var(--accent);flex-shrink:0}

/* ===== ANIMATIONS ===== */
@keyframes fadeUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}
.fade-in{opacity:0;transform:translateY(24px);transition:opacity .6s ease,transform .6s ease}
.fade-in.visible{opacity:1;transform:translateY(0)}

/* ===== PRODUCT DEMO ===== */
.demo-accordion{max-width:768px;margin:0 auto}
.demo-item{border:1px solid var(--gray-200);border-radius:var(--radius);margin-bottom:12px;overflow:hidden}
.demo-trigger{width:100%;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;font-size:1rem;font-weight:600;text-align:left;background:transparent;transition:var(--transition)}
.demo-trigger:hover{background:var(--gray-50)}
.demo-content{max-height:0;overflow:hidden;transition:max-height .3s ease}
.demo-content-inner{padding:0 24px 20px;color:var(--gray-500);font-size:.95rem;line-height:1.7}

/* ===== BUSINESS FIT ===== */
.business-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:24px}
.business-card{background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius-lg);padding:32px;text-align:center;transition:var(--transition)}
.business-card:hover{box-shadow:var(--shadow-lg);transform:translateY(-4px)}
.business-card .b-icon{font-size:2.5rem;margin-bottom:12px}
.business-card h3{font-size:1.1rem;font-weight:700;margin-bottom:8px}
.business-card p{font-size:.9rem;color:var(--gray-500)}

